package dev.wiktor.unboundhorizons.cubic;

import dev.wiktor.unboundhorizons.vertical.VerticalWorldBorder;

/**
 * Deterministic XYZ section generator. Terrain is generated by 16-block
 * cubes, NOT by generating or allocating a 60-million-block-tall X/Z
 * column. Every calculation uses ABSOLUTE X,Y,Z coordinates and a seed,
 * so carving, ore veins and liquid basins match across section edges.
 *
 * This generates an independent virtual cubic world; it is not the native
 * Minecraft chunk generator until the networking, lighting, section tickets,
 * physics and biome pipeline have been replaced as well.
 */
public final class CubicTerrainGenerator {
    private static final long BIOME_HOT = 0xE2B659DF31AB4237L;
    private static final long BIOME_WET = 0x97D3958C92F5FD1BL;
    private static final long BIOME_ODD = 0x11CA319C57D0C987L;
    private static final long CAVES = 0x59AF9321C4D2BDE1L;
    private static final long TUNNELS = 0xC1DC5BEB174E7C51L;
    private static final long ORE_VEINS = 0x76A13BDFCDBE773DL;
    private static final long ORE_TYPE = 0x1131B4EFDE27AB81L;
    private static final long POOLS = 0xAB67208E0B5816F3L;
    private static final long ROCKS = 0xBEBA7CD6F18729AFL;
    private static final long SKY = 0x9E3779B97F4A7C15L;

    private final long seed;

    public CubicTerrainGenerator(long seed) {
        this.seed = seed;
    }

    public long seed() { return seed; }

    /**
     * Biomes are truly 3D: changing Y while keeping X/Z fixed can change
     * the biome. The center of the cubic chunk owns its biome category.
     */
    public CubicBiome biomeAt(int x, int y, int z) {
        if (y >= 320) return CubicBiome.SKY_ISLANDS;
        if (y > -64) return CubicBiome.DEEP_SLATE;
        int cx = Math.floorDiv(x, 16) * 16 + 8;
        int cy = Math.floorDiv(y, 16) * 16 + 8;
        int cz = Math.floorDiv(z, 16) * 16 + 8;

        double heat = noise(cx / 230.0, cy / 360.0, cz / 230.0, BIOME_HOT);
        double wet = noise(cx / 210.0, cy / 270.0, cz / 210.0, BIOME_WET);
        double odd = noise(cx / 185.0, cy / 310.0, cz / 185.0, BIOME_ODD);

        if (heat > 0.22 && wet < 0.12) return CubicBiome.MAGMA_CHAMBERS;
        if (heat < -0.22 && wet < -0.02) return CubicBiome.BASALT_RIFTS;
        if (wet > 0.24) return CubicBiome.FLOODED_DEPTHS;
        if (odd > 0.23) return CubicBiome.CRYSTAL_CAVERNS;
        if (odd < -0.24) return CubicBiome.SCULK_TRENCH;
        if (wet > -0.07) return CubicBiome.LUSH_ABYSS;
        return CubicBiome.DRIPSTONE_GROTTO;
    }

    /**
     * Procedural base at an absolute position. Does not allocate a section.
     * Deliberately returns AIR outside the intended playable Y border.
     */
    public byte blockAt(int x, int y, int z) {
        if (!VerticalWorldBorder.isInsidePlayableY(y)) return CubicBlocks.AIR;
        return generated(x, y, z, biomeAt(x, y, z));
    }

    /**
     * Generates exactly one cube, including only its real 4096 blocks.
     * Adjacent cubes are repeatable and order-independent.
     */
    public CubicChunk generate(int sx, int sy, int sz) {
        long wx = (long)sx * 16L;
        long wy = (long)sy * 16L;
        long wz = (long)sz * 16L;
        if (wx < -30_000_015L || wx > 30_000_000L
             || wy < -30_000_015L || wy > 30_000_000L
             || wz < -30_000_015L || wz > 30_000_000L) {
            throw new IllegalArgumentException("Cubic chunk origin is outside the world");
        }
        byte[] blocks = new byte[CubicChunk.VOLUME];
        CubicBiome biome = biomeAt((int)wx + 8,(int)wy + 8,(int)wz + 8);
        for (int ly = 0; ly < 16; ly++) {
            int y = (int)wy + ly;
            for (int lz = 0; lz < 16; lz++) {
                int z = (int)wz + lz;
                for (int lx = 0; lx < 16; lx++) {
                    int x = (int)wx + lx;
                    int index = (ly << 8) | (lz << 4) | lx;
                    if (y < VerticalWorldBorder.MIN_PLAYABLE_Y
                        || y > VerticalWorldBorder.MAX_PLAYABLE_Y) {
                        blocks[index] = CubicBlocks.AIR;
                    } else {
                        blocks[index] = generated(x,y,z,biome);
                    }
                }
            }
        }
        return new CubicChunk(sx,sy,sz,biome,blocks);
    }

    private byte generated(int x, int y, int z, CubicBiome biome) {
        // Sky landscapes are sparse floating-island strata every 512 blocks.
        // They are not a 30-million-block solid slab.
        if (y >= 320) {
            double distance = Math.abs(Math.floorMod(y, 512) - 256);
            if (distance > 72) return CubicBlocks.AIR;
            double island = noise(x / 64.0,y / 44.0,z / 64.0,SKY)
                + 0.35 * noise(x / 180.0,y / 90.0,z / 180.0,ROCKS);
            if (island <= -0.04 + distance * 0.004) return CubicBlocks.AIR;
            if (island > 0.44) return CubicBlocks.AMETHYST;
            if (island > 0.18) return CubicBlocks.CALCITE;
            return (y & 7) == 0 ? CubicBlocks.TUFF : CubicBlocks.STONE;
        }

        if (y >= 65) return CubicBlocks.AIR;
        if (y == 64) return CubicBlocks.GRASS;
        if (y >= -32) return y >= 60 ? CubicBlocks.DIRT : CubicBlocks.STONE;

        // Continuous multi-scale noise gives caves and connecting tunnels
        // across ALL 3 axes, even at ultra-negative Y (no old Y cutoff).
        double cavern = noise(x / 45.0,y / 35.0,z / 45.0,CAVES);
        double tunnel = Math.abs(noise(x / 68.0,y / 48.0,z / 68.0,TUNNELS));
        boolean open = cavern > 0.30 || tunnel < 0.105;

        double basin = noise(x / 83.0,y / 58.0,z / 83.0,POOLS);
        boolean poolLevel = Math.floorMod(y + (int)(basin * 24), 96) < 31;

        if (open) {
            // Real liquid volumes, not "everything beneath -64 is lava":
            // only selected natural cave basins become lakes; other caves
            // stay dry and traversable.
            if (basin > -0.04 && poolLevel) {
                if (biome == CubicBiome.FLOODED_DEPTHS || biome == CubicBiome.LUSH_ABYSS) {
                    return CubicBlocks.WATER;
                }
                if (biome == CubicBiome.MAGMA_CHAMBERS || biome == CubicBiome.BASALT_RIFTS) {
                    return CubicBlocks.LAVA;
                }
                if (basin > 0.55) {
                    return (y % 5 == 0) ? CubicBlocks.LAVA : CubicBlocks.WATER;
                }
            }
            return CubicBlocks.AIR;
        }

        // Ores are NOT restricted to vanilla's original Y distribution.
        // Veins follow a separate continuous 3D noise field at any depth.
        double vein = noise(x / 10.0,y / 9.0,z / 10.0,ORE_VEINS);
        if (vein > 0.49) {
            double selection = noise(x / 83.0,y / 105.0,z / 83.0,ORE_TYPE);
            if (selection > 0.48) return CubicBlocks.DIAMOND_ORE;
            if (selection > 0.28) return CubicBlocks.GOLD_ORE;
            if (selection > 0.10) return CubicBlocks.REDSTONE_ORE;
            if (selection > -0.12) return CubicBlocks.IRON_ORE;
            if (selection > -0.29) return CubicBlocks.LAPIS_ORE;
            if (selection > -0.42) return CubicBlocks.COPPER_ORE;
            if (biome == CubicBiome.MAGMA_CHAMBERS && selection < -0.56) {
                return CubicBlocks.ANCIENT_DEBRIS;
            }
            return CubicBlocks.COAL_ORE;
        }

        // Nonempty biome geology: different caverns don't all have the
        // same featureless layer of deepslate.
        double stone = noise(x / 32.0,y / 29.0,z / 32.0,ROCKS);
        switch (biome) {
            case MAGMA_CHAMBERS:
                return stone > 0.0 ? CubicBlocks.BASALT : CubicBlocks.BLACKSTONE;
            case BASALT_RIFTS:
                return stone > 0.25 ? CubicBlocks.OBSIDIAN : CubicBlocks.BASALT;
            case FLOODED_DEPTHS:
                return stone > 0.25 ? CubicBlocks.CLAY : CubicBlocks.TUFF;
            case CRYSTAL_CAVERNS:
                return stone > 0.36 ? CubicBlocks.AMETHYST :
                    stone > 0.0 ? CubicBlocks.CALCITE : CubicBlocks.DEEPSLATE;
            case LUSH_ABYSS:
                return stone > 0.33 ? CubicBlocks.MOSS : CubicBlocks.DEEPSLATE;
            case SCULK_TRENCH:
                return stone > 0.08 ? CubicBlocks.SCULK : CubicBlocks.DEEPSLATE;
            case DRIPSTONE_GROTTO:
                return stone > 0.10 ? CubicBlocks.DRIPSTONE : CubicBlocks.DEEPSLATE;
            default:
                return stone > 0.44 ? CubicBlocks.TUFF : CubicBlocks.DEEPSLATE;
        }
    }

    private static long avalanche(long value) {
        value ^= value >>> 30; value *= 0xBF58476D1CE4E5B9L;
        value ^= value >>> 27; value *= 0x94D049BB133111EBL;
        return value ^ (value >>> 31);
    }

    private double lattice(long x,long y,long z,long salt) {
        long n = seed ^ salt ^ x * 0x9E3779B97F4A7C15L
            ^ y * 0xC2B2AE3D27D4EB4FL ^ z * 0x165667B19E3779F9L;
        return ((avalanche(n) >>> 11) * 0x1.0p-53) * 2.0 - 1.0;
    }

    private static double smooth(double t) { return t * t * (3.0 - 2.0 * t); }
    private static double lerp(double a,double b,double t) { return a + (b-a)*t; }

    private double noise(double x,double y,double z,long salt) {
        long ix=(long)Math.floor(x),iy=(long)Math.floor(y),iz=(long)Math.floor(z);
        double fx=smooth(x-ix),fy=smooth(y-iy),fz=smooth(z-iz);
        double a=lerp(lattice(ix,iy,iz,salt),lattice(ix+1,iy,iz,salt),fx);
        double b=lerp(lattice(ix,iy,iz+1,salt),lattice(ix+1,iy,iz+1,salt),fx);
        double c=lerp(lattice(ix,iy+1,iz,salt),lattice(ix+1,iy+1,iz,salt),fx);
        double d=lerp(lattice(ix,iy+1,iz+1,salt),lattice(ix+1,iy+1,iz+1,salt),fx);
        return lerp(lerp(a,b,fz),lerp(c,d,fz),fy);
    }
}
